-- the map: which places it shows, in journey order, and each place's picture
ALTER TABLE ar_curriculum_domain ADD COLUMN map_order INTEGER;
ALTER TABLE ar_curriculum_domain ADD COLUMN cover_key TEXT;
UPDATE ar_curriculum_domain SET map_order = CASE slug
  WHEN 'home_family' THEN 1 WHEN 'children_upbringing' THEN 2 WHEN 'food_drink' THEN 3 WHEN 'market_shopping' THEN 4
  WHEN 'education_school' THEN 5 WHEN 'conversations' THEN 6 WHEN 'common_verbs' THEN 7 WHEN 'prophetic_duas' THEN 8
  WHEN 'body_health' THEN 9 WHEN 'city_directions' THEN 10 WHEN 'travel_transport' THEN 11 WHEN 'work_profession' THEN 12
  WHEN 'worship_ritual' THEN 13 WHEN 'hadith_daily' THEN 14 WHEN 'quran_frequent' THEN 15 WHEN 'idioms' THEN 16
  WHEN 'moral_stories' THEN 17 WHEN 'companion_stories' THEN 18 WHEN 'early_stories' THEN 19 END;
-- times of the day and the year on the map, and the road reordered as a day (owner, 2026-10-25: "morning, night, all possible")
INSERT OR IGNORE INTO ar_curriculum_domain (id, slug, title, title_ar, description, sort_order) VALUES ('01ARDOM000000000000041','morning_routine','Morning','الصَّبَاحُ','Waking, washing, praying, breakfast and setting off',14), ('01ARDOM000000000000042','evening_routine','Evening','الْمَسَاءُ','Coming home, family time, homework and dinner',15), ('01ARDOM000000000000043','night_routine','Night','اللَّيْلُ','Getting ready for bed, the night duʿās and sleep',16), ('01ARDOM000000000000044','weekend_friday','Friday & the Weekend','الْجُمُعَةُ وَالْعُطْلَةُ','Friday prayer, visits, outings and rest',17), ('01ARDOM000000000000045','ramadan_eid','Ramadan & Eid','رَمَضَانُ وَالْعِيدُ','Suhur, fasting, iftar, tarawih and Eid',18); UPDATE ar_curriculum_domain SET map_order = CASE slug WHEN 'morning_routine' THEN 1 WHEN 'home_family' THEN 2 WHEN 'food_drink' THEN 3 WHEN 'children_upbringing' THEN 4 WHEN 'education_school' THEN 5 WHEN 'market_shopping' THEN 6 WHEN 'work_profession' THEN 7 WHEN 'city_directions' THEN 8 WHEN 'travel_transport' THEN 9 WHEN 'body_health' THEN 10 WHEN 'worship_ritual' THEN 11 WHEN 'evening_routine' THEN 12 WHEN 'night_routine' THEN 13 WHEN 'weekend_friday' THEN 14 WHEN 'weather_seasons' THEN 15 WHEN 'ramadan_eid' THEN 16 WHEN 'conversations' THEN 17 WHEN 'common_verbs' THEN 18 WHEN 'prophetic_duas' THEN 19 WHEN 'hadith_daily' THEN 20 WHEN 'quran_frequent' THEN 21 WHEN 'idioms' THEN 22 WHEN 'moral_stories' THEN 23 WHEN 'companion_stories' THEN 24 WHEN 'early_stories' THEN 25 ELSE NULL END;
-- neighbours, government office, hospital, pharmacy, the human body (owner, 2026-10-25)
INSERT OR IGNORE INTO ar_curriculum_domain (id, slug, title, title_ar, description, sort_order) VALUES ('01ARDOM000000000000046','neighbours','Neighbours','الْجِيرَانُ','Greeting, visiting and helping the people next door',19), ('01ARDOM000000000000047','government_office','Government Office','الدَّوَائِرُ الْحُكُومِيَّةُ','Forms, queues, passports and appointments',20), ('01ARDOM000000000000048','hospital','Hospital','الْمُسْتَشْفَى','Emergency, wards, nurses, tests and visiting',21), ('01ARDOM000000000000049','pharmacy','Pharmacy','الصَّيْدَلِيَّةُ','Medicines, doses and asking the pharmacist',22), ('01ARDOM000000000000050','human_body','The Human Body','جِسْمُ الْإِنْسَانِ','The parts of the body and how they feel',23); UPDATE ar_curriculum_domain SET map_order = CASE slug WHEN 'morning_routine' THEN 1 WHEN 'home_family' THEN 2 WHEN 'food_drink' THEN 3 WHEN 'children_upbringing' THEN 4 WHEN 'neighbours' THEN 5 WHEN 'education_school' THEN 6 WHEN 'market_shopping' THEN 7 WHEN 'work_profession' THEN 8 WHEN 'city_directions' THEN 9 WHEN 'government_office' THEN 10 WHEN 'travel_transport' THEN 11 WHEN 'human_body' THEN 12 WHEN 'body_health' THEN 13 WHEN 'pharmacy' THEN 14 WHEN 'hospital' THEN 15 WHEN 'worship_ritual' THEN 16 WHEN 'evening_routine' THEN 17 WHEN 'night_routine' THEN 18 WHEN 'weekend_friday' THEN 19 WHEN 'weather_seasons' THEN 20 WHEN 'ramadan_eid' THEN 21 WHEN 'conversations' THEN 22 WHEN 'common_verbs' THEN 23 WHEN 'prophetic_duas' THEN 24 WHEN 'hadith_daily' THEN 25 WHEN 'quran_frequent' THEN 26 WHEN 'idioms' THEN 27 WHEN 'moral_stories' THEN 28 WHEN 'companion_stories' THEN 29 WHEN 'early_stories' THEN 30 ELSE NULL END; UPDATE kmaps_cache_version SET version = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE family='content';
